//! display/dc/inc/hw/dwb.h + dcn20/dcn20_dwb.{h,c} (Linux 6.18.55), with the
//! `dwbc20_regs`/`dwbc20_shift`/`dwbc20_mask` table of dcn20_resource.c: the
//! display writeback controller (DWBC) of Renoir's resource pool. Renoir reuses
//! the dcn20 DWBC; the pool creates `res_cap_rn.num_dwb` (1) of them.
//!
//! `dcn20_dwbc_create` → `dcn20_dwbc_construct` stores the instance, funcs
//! identity and register pointers; it writes no register (the writeback
//! programming is hwss-stage). The register tables are machine-generated by
//! `dcgen.py` from `DWBC_COMMON_REG_LIST_DCN2_0` /
//! `DWBC_COMMON_MASK_SH_LIST_DCN2_0` (dwbc's reg list uses `SRI2_DWB`, whose
//! offset is register-name-only, and its mask list the `SF_DWB` field macro).
#![allow(dead_code)]

use crate::dc_resource::resource_pool;
use crate::regs::*;
use alloc::boxed::Box;

/// `#define MAX_DWB_PIPES` (hw_shared.h).
pub const MAX_DWB_PIPES: usize = 1;

/// Which `dwbc_funcs` vtable the base points at (dcn20_dwb.c).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum dwbc_funcs {
    dcn20_dwbc_funcs,
}

/// `struct dwbc` (inc/hw/dwb.h): the writeback controller base. Ported
/// grow-as-reached — the construct touches only funcs and inst (Linux' `ctx` is
/// not stored, see `clock_source`); the status/params fields join with the
/// writeback programming ops.
#[derive(Default)]
pub struct dwbc {
    pub funcs: Option<dwbc_funcs>,
    pub inst: u32,
}

/// `struct dcn20_dwbc` (dcn20_dwb.h): the concrete DWBC.
#[derive(Default)]
pub struct dcn20_dwbc {
    pub base: dwbc,
    pub dwbc_regs: Option<&'static dcn20_dwbc_registers>,
    pub dwbc_shift: Option<&'static dcn20_dwbc_shift>,
    pub dwbc_mask: Option<&'static dcn20_dwbc_mask>,
}

/// `dcn20_dwbc_construct` (dcn20_dwb.c): store the instance, funcs and registers.
pub fn dcn20_dwbc_construct(
    dwbc20: &mut dcn20_dwbc,
    dwbc_regs: &'static dcn20_dwbc_registers,
    dwbc_shift: &'static dcn20_dwbc_shift,
    dwbc_mask: &'static dcn20_dwbc_mask,
    inst: u32,
) {
    dwbc20.base.inst = inst;
    dwbc20.base.funcs = Some(dwbc_funcs::dcn20_dwbc_funcs);
    dwbc20.dwbc_regs = Some(dwbc_regs);
    dwbc20.dwbc_shift = Some(dwbc_shift);
    dwbc20.dwbc_mask = Some(dwbc_mask);
}

/// `dcn20_dwbc_create` (dcn20_resource.c): allocate and construct `num_dwb`
/// DWBCs into `pool.dwbc`. Returns true (allocation does not fail here).
pub fn dcn20_dwbc_create(pool: &mut resource_pool) -> bool {
    let pipe_count = pool.res_cap.unwrap().num_dwb;
    for i in 0..pipe_count as usize {
        let mut dwbc20 = Box::new(dcn20_dwbc::default());
        dcn20_dwbc_construct(&mut dwbc20, &DWBC_REGS[i], &DWBC_SHIFT, &DWBC_MASK, i as u32);
        pool.dwbc[i] = Some(dwbc20);
    }
    true
}

